body:
## Problem statement
I'm trying to express an object with a object field. That field allows keys of any name. Something like this...

```json
{
   "entree_choice": {
        "james": "Beef",
        "julia": "Vegan",
        ...
    }
}
```

The generated code contains an extra dereference that on line 75 that causes it to not compile. 

```shellsession
$ go build
# models
./my_first_object.go:75: invalid indirect of m.EntreeChoice[k] (type string)
```

Here's a yml spec.

Generated code
```go
package models

// This file was generated by the swagger tool.
// Editing this file might prove futile when you re-run the swagger generate command

import (
	"encoding/json"

	strfmt "github.com/go-openapi/strfmt"
	"github.com/go-openapi/swag"

	"github.com/go-openapi/errors"
	"github.com/go-openapi/validate"
)

// MyFirstObject my first object
// swagger:model MyFirstObject
type MyFirstObject struct {

	// entree choice
	EntreeChoice map[string]string `json:"entree_choice,omitempty"`
}

// Validate validates this my first object
func (m *MyFirstObject) Validate(formats strfmt.Registry) error {
	var res []error

	if err := m.validateEntreeChoice(formats); err != nil {
		// prop
		res = append(res, err)
	}

	if len(res) > 0 {
		return errors.CompositeValidationError(res...)
	}
	return nil
}

// additional properties value enum
var myFirstObjectEntreeChoiceValueEnum []interface{}

func init() {
	var res []string
	if err := json.Unmarshal([]byte(`["Beef","Vegan"]`), &res); err != nil {
		panic(err)
	}
	for _, v := range res {
		myFirstObjectEntreeChoiceValueEnum = append(myFirstObjectEntreeChoiceValueEnum, v)
	}
}
func (m *MyFirstObject) validateEntreeChoiceValueEnum(path, location string, value string) error {
	if err := validate.Enum(path, location, value, myFirstObjectEntreeChoiceValueEnum); err != nil {
		return err
	}
	return nil
}

func (m *MyFirstObject) validateEntreeChoice(formats strfmt.Registry) error {

	if swag.IsZero(m.EntreeChoice) { // not required
		return nil
	}

	if err := validate.Required("entree_choice", "body", m.EntreeChoice); err != nil {
		return err
	}

	for k := range m.EntreeChoice {

		if err := validate.Required("entree_choice"+"."+k, "body", m.EntreeChoice[k]); err != nil {
			return err
		}

		// value enum
		if err := m.validateEntreeChoiceValueEnum("entree_choice"+"."+k, "body", *m.EntreeChoice[k]); err != nil {
			return err
		}

	}

	return nil
}
```

## Swagger specification
```yaml
swagger: '2.0'
info:
  title: Test API
  description: my test
  version: "0.1.0"

host: test.test.com

schemes:
  - https

basePath: /

produces:
  - application/json
consumes:
  - application/json

paths:
  /:
    get:
      summary: Find a thing
      description: It's acool thing
      tags:
        - Root
      responses:
        307:
          description: Redirect to a thing.

definitions:
  MyFirstObject:
    type: object
    properties:
      entree_choice:
        type: object
        additionalProperties:
          type: string
          enum:
            - Beef
            - Vegan
```

## Steps to reproduce
```shellsession
/usr/local/Cellar/go-swagger/0.7.4/bin/swagger generate model --spec=models/test.yml
cd models
go build
```
